import sys, os
sys.path.append('storage/ariadne')

import optax
import jax.numpy as jnp
from losses import mae_with_temporal_curvature
from models_mlp_rankgate import FactGlobalMLP_LN_RankGate, extract_gates, export_rankgate_analysis

BASE_SEED = 42
BATCH_SIZE = 8
LAM_GATE = 1e-5

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'rank_k': 320,
        'proj_rank': 48,
        'hidden': 512,
        'hidden2': 512,
        'gamma_start': 0.25,
        'gamma_end': 0.99
    }

class Wrapper:
    def __init__(self, **kw):
        self.model = FactGlobalMLP_LN_RankGate(**kw)
        self.needs_rng = False
    def init(self, rng_key, dummy_input):
        return self.model.init(rng_key, dummy_input, training=True)
    def apply(self, params, x, training=False, mutable=None, rngs=None):
        return self.model.apply(params, x, training=training)

def create_network(hparams):
    return Wrapper(
        rank_k=int(hparams.get('rank_k', 320)),
        proj_rank=int(hparams.get('proj_rank', 48)),
        hidden=int(hparams.get('hidden', 512)),
        hidden2=int(hparams.get('hidden2', 512)),
        gamma_start=float(hparams.get('gamma_start', 0.25)),
        gamma_end=float(hparams.get('gamma_end', 0.99)),
    )

def _l1_on_gates(params):
    try:
        from flax.linen import sigmoid
    except Exception:
        sigmoid = lambda z: 1 / (1 + jnp.exp(-z))
    try:
        g = params['params']['gate_raw']
    except Exception:
        g = params.get('gate_raw', None)
    if g is None:
        return 0.0
    s = sigmoid(g)
    return jnp.sum(jnp.abs(s))

def compute_loss(predictions, targets, params, x):
    base = mae_with_temporal_curvature(predictions, targets, params, x, lam=1e-4)
    l1 = _l1_on_gates(params)
    return base + LAM_GATE * l1

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adam(learning_rate=learning_rate, eps=1e-8)
    )

def complete(params, opt_state, trial_data):
    out_dir = "storage/ariadne/analyses/rankgate_mlp_ln"
    export_rankgate_analysis(params, trial_data, out_dir)
